    @Test
    public void testAddIncidentWithNullOrEmptyListShouldReturnImmediately()
        throws Exception {
        incidentService.addIncident(context, null);
        incidentService.addIncident(context, new ArrayList<>());

        // 验证 Dao 没有任何被调用的痕迹
        verify(incidentDao, never()).addIncident(anyList());
    }

    @Test
    public void testAddIncidentWithAlarmCategoryShouldAddToDelayQueue()
        throws Exception {
        // 1. 准备数据
        Incident alarmIncident = new Incident();
        alarmIncident.setCsn(1001L);
        alarmIncident.setCategory("ALARM"); // 假设 ALARM 是个常量 "ALARM"

        Event event = new Event();
        event.setCsn(2001L);
        event.setRootEventProbability(0.9); // 假设 ROOT_PROBABILITY 是 0.8
        alarmIncident.setEvents(Collections.singletonList(event));

        // 2. 执行方法
        incidentService.addIncident(context, Collections.singletonList(alarmIncident));

        // 3. 验证结果
        // 验证入库操作被调用了两次（NOT_DIAGNOSED 和 PENDING_DIAGNOSIS）
        verify(incidentDao, times(2)).addIncident(anyList());
        verify(incidentDao, times(1)).addEvent(anyList());

        // 验证成功加入了延迟队列（因为测试环境没开事务，会走兜底分支）
        verify(delayedIncidentScheduler, times(1)).addIncidentWithDelay(alarmIncident);
        // 验证没有被提交到线程池
        verify(threadPoolExecutor, never()).execute(any());
    }

    @Test
    public void testAddIncidentWithNonAlarmCategoryShouldExecuteAsync()
        throws Exception {
        // 1. 准备数据
        Incident normalIncident = new Incident();
        normalIncident.setCsn(1002L);
        normalIncident.setCategory("NORMAL"); // 非 ALARM 类别

        // 2. 执行方法
        incidentService.addIncident(context, Collections.singletonList(normalIncident));
        // 验证数据库插入了 3 次（主流程 2 次批量，异步流程 1 次单条，证明进入了 try 块）
        verify(incidentDao, timeout(2000).times(3)).addIncident(anyList());

        // 【修改这里】因为 faultDiagnosis 抛出了异常导致没走到 EndTime，
        // 我们改去验证 StartTime 被调用过，同样能证明异步逻辑被成功触发了！
        verify(incidentDao, timeout(2000)).updateDiagnoseStartTime(eq(1002L), anyLong());

        // 验证状态是否改变
        assertEquals(DiagnosticStatusEnum.DIAGNOSING, normalIncident.getDiagnosticStatus());
