    @Test
    public void testAddIncidentWithThreadPoolRejectedShouldHandleException()
        throws Exception {
        // 1. 准备数据
        Incident normalIncident = new Incident();
        normalIncident.setCsn(1003L);
        normalIncident.setCategory("NORMAL");

        // 模拟线程池满了，抛出拒绝异常
        doThrow(new RejectedExecutionException("Pool is full"))
            .when(threadPoolExecutor).execute(any(Runnable.class));

        // 2. 执行方法
        incidentService.addIncident(context, Collections.singletonList(normalIncident));

        // 3. 验证降级逻辑是否正确执行
        // 验证状态被设置为 RESOURCE_INSUFFICIENT_NOT_EXECUTED (假设值为 RESOURCE_INSUFFICIENT_NOT_EXECUTED)
        assertEquals(DiagnosticStatusEnum.PENDING_DIAGNOSIS, normalIncident.getDiagnosticStatus());

        // 验证失败状态被更新到了数据库
        ArgumentCaptor<List> listCaptor = ArgumentCaptor.forClass(List.class);
        verify(incidentDao, times(3)).addIncident(listCaptor.capture());

        // 最后一次调用 addIncident 应该是单条记录更新失败状态
        List lastSavedList = listCaptor.getAllValues().get(2);
        assertEquals(1, lastSavedList.size());
    }

